do $$begin if not exists(select 1 from public.patient_clinical_publications p join public.patient_care_plans plan on plan.id=p.plan_id and plan.active where p.user_id='71000000-0000-4000-8000-000000000001' and p.actor_id='71000000-0000-4000-8000-000000000005') then raise exception 'TEST newly assigned doctor cannot publish fresh coverage';end if;end$$;
rollback to new_collection;
insert into public.patient_care_plans(id,user_id,clinician,published_at,instructions,active,retired_at) values('71000000-0000-4000-8000-000000000050',(select uid from ctx),'Synthetic clinician',now()-interval '2 hours','Historical fixture',false,now());
insert into public.patient_care_medications(id,user_id,plan_id,name,dose,instructions,times,start_date,effective_at) values('71000000-0000-4000-8000-000000000051',(select uid from ctx),'71000000-0000-4000-8000-000000000050','Historical fixture','Test dose','Test instruction',array[timezone('Asia/Yerevan',date_trunc('minute',now()-interval '1 minute'))::time],timezone('Asia/Yerevan',now()-interval '2 hours')::date,now()-interval '2 hours');
insert into public.patient_dose_events(user_id,medication_id,due_at,status) select uid,'71000000-0000-4000-8000-000000000051',date_trunc('minute',now()-interval '1 minute'),'taken' from ctx;
select pg_temp.password_actor('71000000-0000-4000-8000-000000000001');
set local role authenticated;
select public.report_patient_dose_versioned('71000000-0000-4000-8000-000000000051',date_trunc('minute',now()-interval '1 minute'),'skipped',1);
select pg_temp.must_fail(format('select public.report_patient_dose_versioned(%L,%L,''taken'',0)','71000000-0000-4000-8000-000000000051',date_trunc('minute',now()-interval '2 minutes')),'plan unavailable');
reset role;
do $$begin if (select count(*) from public.patient_dose_event_history where medication_id='71000000-0000-4000-8000-000000000051' and plan_id='71000000-0000-4000-8000-000000000050')<>2 then raise exception 'TEST dose correction lost original plan history';end if;end$$;
rollback;
\echo Real publication source, receipt, consultation, CAS, atomic outbox and privacy checks pass.
